create or replace function private.command_authorize_charge_adjustment(p_organization_id uuid,p_charge_id uuid,p_adjustment_type text,p_amount numeric,p_reason text,p_idempotency_key text) returns uuid language plpgsql security definer set search_path='pg_catalog','app','private' as $$ declare v_id uuid; v_balance numeric; v_actor uuid:=(select auth.uid()); v_type text:=lower(trim(coalesce(p_adjustment_type,'waiver'))); begin if not private.is_presidency(p_organization_id) then raise exception 'Only Presidencia can authorize debt adjustments'; end if; if v_type not in ('waiver','discount','correction') then raise exception 'Invalid adjustment type'; end if; if p_amount is null or p_amount<=0 then raise exception 'Amount must be greater than zero'; end if; if coalesce(length(trim(p_reason)),0)<5 then raise exception 'Adjustment reason required'; end if; if p_idempotency_key is null or length(trim(p_idempotency_key))<8 then raise exception 'Idempotency key required'; end if; perform 1 from app.charges where id=p_charge_id and organization_id=p_organization_id and status='posted' for update; if not found then raise exception 'Charge not found'; end if; select balance_due into v_balance from app.charge_balances where id=p_charge_id; if coalesce(v_balance,0)<=0 then raise exception 'Charge has no outstanding balance'; end if; if p_amount>v_balance+0.005 then raise exception 'Adjustment exceeds outstanding balance'; end if; select id into v_id from app.charge_adjustment_authorizations where organization_id=p_organization_id and idempotency_key=trim(p_idempotency_key); if v_id is not null then return v_id; end if; insert into app.charge_adjustment_authorizations(organization_id,charge_id,adjustment_type,amount,reason,status,authorized_by_user_id,idempotency_key) values(p_organization_id,p_charge_id,v_type,p_amount,trim(p_reason),'approved',v_actor,trim(p_idempotency_key)) returning id into v_id; insert into app.domain_events(organization_id,event_type,aggregate_type,aggregate_id,payload,actor_user_id,request_id) values(p_organization_id,'ChargeAdjustmentAuthorized','charge',p_charge_id,jsonb_build_object('authorizationId',v_id,'type',v_type,'amount',p_amount,'reason',trim(p_reason)),v_actor,trim(p_idempotency_key)); return v_id; end $$;
create or replace function private.command_post_authorized_adjustment(p_organization_id uuid,p_authorization_id uuid) returns uuid language plpgsql security definer set search_path='pg_catalog','app','private' as $$ declare v_auth app.charge_adjustment_authorizations%rowtype; v_id uuid; v_balance numeric; v_actor uuid:=(select auth.uid()); begin if not private.has_module_access(p_organization_id,'accounting',true) then raise exception 'Accounting permission required'; end if; select * into v_auth from app.charge_adjustment_authorizations where id=p_authorization_id and organization_id=p_organization_id for update; if not found then raise exception 'Authorization not found'; end if; if v_auth.status='consumed' then select id into v_id from app.charge_adjustments where organization_id=p_organization_id and authorization_id=v_auth.id; if v_id is not null then return v_id; end if; end if; if v_auth.status<>'approved' then raise exception 'Authorization is not available'; end if; select balance_due into v_balance from app.charge_balances where id=v_auth.charge_id; if coalesce(v_balance,0)<=0 then raise exception 'Charge has no outstanding balance'; end if; if v_auth.amount>v_balance+0.005 then raise exception 'Authorized amount now exceeds outstanding balance'; end if; insert into app.charge_adjustments(organization_id,charge_id,adjustment_type,amount,reason,status,idempotency_key,direction,authorization_id,authorized_by_user_id,posted_by_user_id,posted_at,created_at,updated_at) values(p_organization_id,v_auth.charge_id,v_auth.adjustment_type,v_auth.amount,v_auth.reason,'posted','approved-adjustment:'||v_auth.id::text,'decrease',v_auth.id,v_auth.authorized_by_user_id,v_actor,now(),now(),now()) returning id into v_id; update app.charge_adjustment_authorizations set status='consumed',consumed_by_user_id=v_actor,consumed_at=now(),updated_at=now() where id=v_auth.id; insert into app.domain_events(organization_id,event_type,aggregate_type,aggregate_id,payload,actor_user_id) values(p_organization_id,'ChargeAdjustmentPosted','charge_adjustment',v_id,jsonb_build_object('authorizationId',v_auth.id,'chargeId',v_auth.charge_id,'amount',v_auth.amount,'authorizedBy',v_auth.authorized_by_user_id,'postedBy',v_actor),v_actor); return v_id; end $$;
create or replace function private.command_revoke_charge_adjustment_authorization(p_organization_id uuid,p_authorization_id uuid,p_reason text) returns void language plpgsql security definer set search_path='pg_catalog','app','private' as $$ declare v_actor uuid:=(select auth.uid()); begin if not private.is_presidency(p_organization_id) then raise exception 'Only Presidencia can revoke debt adjustment authorizations'; end if; if coalesce(length(trim(p_reason)),0)<3 then raise exception 'Revoke reason required'; end if; update app.charge_adjustment_authorizations set status='revoked',revoked_by_user_id=v_actor,revoked_at=now(),revoke_reason=trim(p_reason),updated_at=now() where id=p_authorization_id and organization_id=p_organization_id and status='approved'; if not found then raise exception 'Approved authorization not found'; end if; insert into app.domain_events(organization_id,event_type,aggregate_type,aggregate_id,payload,actor_user_id) values(p_organization_id,'ChargeAdjustmentAuthorizationRevoked','charge_adjustment_authorization',p_authorization_id,jsonb_build_object('reason',trim(p_reason)),v_actor); end $$;
create or replace function private.query_adjustment_authorizations(p_organization_id uuid,p_status text default null) returns table(id uuid,charge_id uuid,player_id uuid,player_name text,charge_concept text,charge_balance numeric,adjustment_type text,amount numeric,reason text,status text,authorized_by_user_id uuid,authorized_at timestamptz,consumed_by_user_id uuid,consumed_at timestamptz) language plpgsql stable security definer set search_path='pg_catalog','app','private' as $$ begin if not (private.is_presidency(p_organization_id) or private.has_module_access(p_organization_id,'accounting',false)) then raise exception 'Not authorized'; end if; return query select a.id,a.charge_id,c.player_id,trim(concat_ws(' ',p.first_name,p.last_name)),c.concept,cb.balance_due,a.adjustment_type,a.amount,a.reason,a.status,a.authorized_by_user_id,a.authorized_at,a.consumed_by_user_id,a.consumed_at from app.charge_adjustment_authorizations a join app.charges c on c.id=a.charge_id and c.organization_id=a.organization_id left join app.charge_balances cb on cb.id=c.id left join app.players p on p.id=c.player_id and p.organization_id=c.organization_id where a.organization_id=p_organization_id and (p_status is null or a.status=p_status) order by a.authorized_at desc,a.id; end $$;
create or replace function public.v2_authorize_charge_adjustment(organization_id uuid,charge_id uuid,adjustment_type text,amount numeric,reason text,idempotency_key text) returns uuid language sql security definer set search_path='pg_catalog','private' as $$ select private.command_authorize_charge_adjustment(organization_id,charge_id,adjustment_type,amount,reason,idempotency_key) $$;
create or replace function public.v2_post_authorized_adjustment(organization_id uuid,authorization_id uuid) returns uuid language sql security definer set search_path='pg_catalog','private' as $$ select private.command_post_authorized_adjustment(organization_id,authorization_id) $$;
create or replace function public.v2_revoke_charge_adjustment_authorization(organization_id uuid,authorization_id uuid,reason text) returns void language sql security definer set search_path='pg_catalog','private' as $$ select private.command_revoke_charge_adjustment_authorization(organization_id,authorization_id,reason) $$;
create or replace function public.v2_adjustment_authorizations(organization_id uuid,status_filter text default null) returns table(id uuid,charge_id uuid,player_id uuid,player_name text,charge_concept text,charge_balance numeric,adjustment_type text,amount numeric,reason text,status text,authorized_by_user_id uuid,authorized_at timestamptz,consumed_by_user_id uuid,consumed_at timestamptz) language sql stable security definer set search_path='pg_catalog','private' as $$ select * from private.query_adjustment_authorizations(organization_id,status_filter) $$;
revoke execute on function public.v2_authorize_charge_adjustment(uuid,uuid,text,numeric,text,text),public.v2_post_authorized_adjustment(uuid,uuid),public.v2_revoke_charge_adjustment_authorization(uuid,uuid,text),public.v2_adjustment_authorizations(uuid,text) from public,anon; grant execute on function public.v2_authorize_charge_adjustment(uuid,uuid,text,numeric,text,text),public.v2_post_authorized_adjustment(uuid,uuid),public.v2_revoke_charge_adjustment_authorization(uuid,uuid,text),public.v2_adjustment_authorizations(uuid,text) to authenticated;;
